package com.yihe.framework.ehr;
import java.util.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;import static com.yihe.framework.ehr.EhrService.*;import static com.yihe.framework.ehr.EhrAccess.*;
public class EmployeeIdentityChecks {
 static void check(String name,boolean ok){if(!ok)throw new AssertionError(name);System.out.println("PASS "+name);}
 static void reject(String name,Runnable fn){try{fn.run();throw new AssertionError(name);}catch(EhrException e){check(name,e.status==422);}}
 public static void main(String[]args){if(!System.getenv("EHR_JDBC_URL").contains("/shayu_3_preview?"))throw new IllegalStateException("preview only");DriverManagerDataSource ds=new DriverManagerDataSource(System.getenv("EHR_JDBC_URL"),System.getenv("EHR_DB_USER"),System.getenv("EHR_DB_PASSWORD"));EhrRepository db=new EhrRepository(ds);EhrService ehr=new EhrService(db);EhrActor a=new EhrActor("IDENTITY-TEST","IDENTITY-TEST","synthetic",true,false);new TransactionTemplate(new DataSourceTransactionManager(ds)).execute(tx->{try{
 String card="11010519491231002X";Map<String,Object>b=map("name","测试职工","code","ID-"+id(),"org","测试单位","sex","女","birth","1980-01-02","identityNumber",card.toLowerCase());Map<String,Object>p=ehr.upsert(a,null,b);String record=str(p.get("id"));check("create_and_read_identity",card.equals(p.get("identityNumber")));check("explicit_identity_used_by_report_matching",card.toLowerCase().equals(new ReportMatchingService(db,ehr).preparedEmployees(a).get(0).get("identityKey")));check("birth_derived_without_changing_gender","1949-12-31".equals(p.get("birth"))&&"女".equals(p.get("sex")));b.put("rowVersion",p.get("rowVersion"));b.remove("identityNumber");p=ehr.upsert(a,record,b);check("older_forms_preserve_identity",card.equals(p.get("identityNumber")));Map<String,Object>duplicate=new LinkedHashMap<>(b);duplicate.put("code","ID-"+id());duplicate.put("identityNumber",card);reject("duplicate_identity_rejected",()->ehr.upsert(a,null,duplicate));b.put("rowVersion",p.get("rowVersion"));b.put("identityNumber","");p=ehr.upsert(a,record,b);check("explicit_clear_persists",str(p.get("identityNumber")).isEmpty());check("legacy_birth_derived","1967-04-01".equals(EmployeeIdentity.birth("130503670401001")));check("empty_identity_no_birth",EmployeeIdentity.birth("").isEmpty());check("legacy_fifteen_digit_supported","130503670401001".equals(EmployeeIdentity.normalize("130503670401001")));reject("masked_identity_rejected",()->EmployeeIdentity.normalize("110105********002X"));reject("bad_checksum_rejected",()->EmployeeIdentity.normalize("110105194912310021"));reject("invalid_birth_date_rejected",()->EmployeeIdentity.normalize("11010519991331002X"));
 }finally{tx.setRollbackOnly();}return null;});}
}
